const payloadHash=value=>sha256(JSON.stringify(value));
async function replay(env,auth,key,operation,hash){const row=await env.DB.prepare("SELECT resource_id,payload_hash FROM issue_idempotency WHERE user_id=?1 AND idempotency_key=?2 AND operation=?3 AND (expires_at IS NULL OR datetime(expires_at)>datetime('now'))").bind(auth.userId,key,operation).first();if(!row)return null;if(row.payload_hash&&row.payload_hash!==hash)throw new ApiError(409,"IDEMPOTENCY_PAYLOAD_MISMATCH","The Idempotency-Key was already used with a different payload.");return row.resource_id}
