export async function handleIssueRequest(request,env,url){
 const path=url.pathname,method=request.method;
 if(method==="GET"&&path==="/api/v1/issues")return listIssues(request,env,url);
 if(method==="POST"&&path==="/api/v1/issues")return createIssue(request,env);
 if(method==="POST"&&path==="/api/v1/issues/bulk")return bulkUpdateIssues(request,env);
 if(method==="GET"&&path==="/api/v1/issues/summary")return summaryIssues(request,env);
 if(method==="GET"&&path==="/api/v1/issues/options")return issueOptions(request,env);
 if(method==="GET"&&path==="/api/v1/issues/form-options")return issueFormOptions(request,env);
 if(method==="POST"&&path==="/api/v1/issues/locations")return createLocation(request,env);
 const locationMatch=path.match(/^\/api\/v1\/issues\/locations\/([^/]+)$/);
 if(method==="DELETE"&&locationMatch)return deleteLocation(request,env,locationMatch[1]);
 const companyTradesMatch=path.match(/^\/api\/v1\/issues\/companies\/([^/]+)\/trades$/);
 if(method==="PUT"&&companyTradesMatch)return updateCompanyTrades(request,env,companyTradesMatch[1]);
 const mediaMatch=path.match(/^\/api\/v1\/issues\/([^/]+)\/media\/([^/]+)\/(thumbnail|original)$/);
 if(method==="GET"&&mediaMatch)return mediaItemContent(request,env,mediaMatch[1],mediaMatch[2],mediaMatch[3]);
 const match=path.match(/^\/api\/v1\/issues\/([^/]+)(?:\/(.*))?$/);if(!match)return null;const [,id,suffix=""]=match;
 if(method==="GET"&&!suffix)return detailIssue(request,env,id);if(method==="PATCH"&&!suffix)return updateDetails(request,env,id);if(method==="POST"&&suffix==="assign")return assignIssue(request,env,id);if(method==="POST"&&suffix==="department/recommend")return recommendDepartment(request,env,id);if(method==="POST"&&suffix==="department/confirm")return confirmDepartment(request,env,id);if(method==="POST"&&suffix==="actions")return addAction(request,env,id);if(method==="POST"&&suffix==="request-completion")return transition(request,env,id,"request");if(method==="POST"&&suffix==="confirm-completion")return transition(request,env,id,"confirm");if(method==="POST"&&suffix==="rework")return transition(request,env,id,"rework");if(method==="POST"&&suffix==="cancel")return transition(request,env,id,"cancel");if(method==="GET"&&suffix==="media/thumbnail")return mediaContent(request,env,id,"thumbnail");if(method==="GET"&&suffix==="media/original")return mediaContent(request,env,id,"original");return null
}
